effect.shader:
vec3 hueShift(vec3 col, float shift) {
vec3 P = vec3(0.55735) * dot(vec3(0.55735), col);
vec3 U = col - P;
vec3 V = cross(vec3(0.55735), U);
col = U * cos(shift * 6.2832) + V * sin(shift * 6.2832) + P;
return max(vec3(0.0), col);
}
float hash(float n) { return fract(sin(n) * 43758.5453123); }
vec3 lensFlare(vec2 uv, vec2 pos) {
vec2 main = uv - pos;
float dist = length(main);
float ang = atan(main.y, main.x);
vec3 f = vec3(0.0);
vec3 colCore = hueShift(vec3(1.0, 0.9, 0.8), flareHue);
vec3 colStreak = hueShift(vec3(0.8, 0.5, 0.2), flareHue);
vec3 colGhost = hueShift(vec3(0.9, 0.8, 1.0), flareHue);
int type = int(floor(flareType + 0.5));
float activeStreak = 0.0;
float activeStar = 0.0;
float activeGhosts = 0.0;
if (type == 0) {
activeStreak = 0.0;
activeStar = 0.0;
activeGhosts = 0.0;
} else if (type == 1) {
activeStreak = 1.0;
activeStar = 0.0;
activeGhosts = 0.2;
} else if (type == 2) {
activeStreak = 0.0;
activeStar = 1.0;
activeGhosts = 0.1;
} else {
activeStreak = 0.3;
activeStar = 0.2;
activeGhosts = 1.0;
}
float sStr = streakStr * activeStreak;
float stStr = starburstStr * activeStar;
float gStr = ghostStr * activeGhosts;
float core = 1.0 / (dist * (20.0 / glowSize) + 0.5);
core = pow(core, 2.0);
f += colCore * core * 2.0;
if (stStr > 0.01) {
float rays = abs(cos(ang * 3.0)) * 0.5 + abs(cos(ang * 12.0)) * 0.2;
rays += smoothstep(0.0, 1.0, abs(sin(ang * 100.0))) * 0.1;
rays *= 0.2 / (dist + 0.1);
f += colCore * rays * stStr;
}
if (sStr > 0.01) {
float vDist = abs(main.y);
float streak = exp(-vDist * 40.0);
streak *= smoothstep(1.5, 0.1, abs(main.x));
f += colStreak * streak * sStr;
}
if (gStr > 0.01) {
vec2 ghostVec = -pos * 0.5;
for (float i = 0.0; i < 5.0; i++) {
float t = fract(i * 0.35 + 0.3);
vec2 gPos = pos + ghostVec * (t * 4.0);
float size = 0.05 + 0.15 * hash(i * 12.3);
float chr = 0.02 * dist;
vec3 ghostCol = vec3(0.0);
float d = length(uv - gPos);
ghostCol.r = smoothstep(size + chr, size - 0.01 + chr, d);
ghostCol.g = smoothstep(size,       size - 0.01,       d);
ghostCol.b = smoothstep(size - chr, size - 0.01 - chr, d);
float hollow = smoothstep(0.0, size * 0.8, d);
ghostCol *= 0.5 + 0.5 * hollow;
float alpha = 0.1 * gStr * (1.0 - t * 0.5);
f += ghostCol * alpha * colGhost;
}
}
return f * intensity;
}
void main() {
vec2 uv = acScreenNorm;
vec2 aspectVec = vec2(acLayerSize.x / acLayerSize.y, 1.0);
vec2 cUV = (uv - 0.5) * aspectVec;
vec2 lightPos = (vec2(posX, 1.0 - posY) - 0.5) * aspectVec;
vec3 col = texture2DCv(inputImg.texture, uv).rgb;
vec3 flare = lensFlare(cUV, lightPos);
col += flare;
col = col * 0.8;
const float a = 2.51;
const float b = 0.03;
const float c = 2.43;
const float d = 0.59;
const float e = 0.14;
col = clamp((col*(a*col+b))/(col*(c*col+d)+e), 0.0, 1.0);
col = pow(col, vec3(1.0/2.2));
gl_FragColor = vec4(col, 1.0);
}
